      acc: [{ l: "National Book Award for Nonfiction, 2020", k: "w", s: "nba-nonfiction" }, { l: "Pulitzer Prize for Biography, 2021", k: "w", s: "pulitzer-biography" }],
      blurb: "The Dead Are Arising: The Life of Malcolm X is a biography of Malcolm X by Les Payne and Tamara Payne. The book was published on September 29, 2020 by Liveright in hardcover format while an audiobook, narrated by actor Dion Graham, was simultaneously released by Recorded Books. Among other honors, the book won the 2020 National Book Award for Nonfiction and the 2021 Pulitzer Prize for Biography.",
      blurbSrc: "wikipedia",
