      acc: [{ l: "Costa Book Award for Poetry, 2017", k: "w", s: "costa-poetry" }],
      blurb: "Inside the Wave is Helen Dunmore's last poetry collection, about impending death, published shortly before her death. In the 2017 Costa Book Awards it won the Poetry Award and the Book of the Year Award.",
      blurbSrc: "wikipedia",
